css:
:root {
  --status-background: #F7F9FB;
  --status-border: #CBD5E1;
  --status-text-color: #527DA5;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.status-widget,
.status-widget * {
  box-sizing: border-box;
}

.status-widget {
  width: 100%;
  height: 100%;
  padding: 3px 5px;
  overflow: hidden;

  font-family: "Segoe UI", Arial, sans-serif;
  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.status-frame {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  width: 100%;
  height: 100%;
  padding: 0 15px;
  overflow: hidden;

  border: 1px solid var(--status-border);
  border-radius: 6px;
  background: var(--status-background);
}

.status-label {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 55%;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: var(--status-text-color);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.2;
}

.status-value {
  display: block;
  flex: 0 1 auto;
  min-width: 0;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: right;

  color: var(--status-text-color);
  font-size: 18px;
  font-weight: 400;
  line-height: 1.2;
}

