"use strict";

(function () {
  /*
   * Edita estos textos para cambiar los estados.
   */
  const STATES = new Map([
    [0, "Sin señal"],
    [1, "Detenida"],
    [2, "En marcha"],
    [3, "Alarma"]
  ]);

  let valueElement = null;
  let lastUpdate = null;

  function render(w) {
    if (!valueElement) return;

    const raw = w ? w.value : null;
    let numericValue = NaN;

    if (typeof raw === "number") {
      numericValue = raw;
    } else if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      numericValue = Number(raw);
    }

    let text = "Sin señal";

    if (Number.isFinite(numericValue)) {
      /*
       * Solo se aceptan coincidencias exactas:
       * un valor como 2.5 no se convierte en 2.
       */
      text = STATES.has(numericValue)
        ? STATES.get(numericValue)
        : "Desconocido";
    }

    valueElement.textContent = text;

    valueElement.setAttribute(
      "aria-label",
      "Estado de línea: " + text
    );
  }

  /* Recibe las actualizaciones de la variable del PLC */
  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    valueElement = document.querySelector(".status-value");

    if (!valueElement) return;

    render(lastUpdate || window.WIDGET || null);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
